UPDATE course
SET status = #{status}, version = version + 1
WHERE course_id = #{courseId} AND deleted_at IS NULL AND version = #{version}

UPDATE course
course_name = #{courseName}, course_code = #{courseCode}, dept_id = #{deptId}, semester = #{semester}, is_public = #{isPublic}, cover_url = #{coverUrl}, description = #{description}, version = version + 1
